import React, { useState } from 'react';
import './HazardAnalysisControls.css';

export const HazardAnalysisControls = ({
  onAnalyzeClick,
  onExportClick,
  location,
  bounds,
  analysisData,
  loading,
  error
}) => {
  const [citySearch, setCitySearch] = useState('');
  const [hazard, setHazard] = useState('heatwave');
  const [startYear, setStartYear] = useState(1990);
  const [endYear, setEndYear] = useState(2020);
  const [regionBy, setRegionBy] = useState('city'); // 'city' or 'map'

  const VITE_API_URL = process.env.VITE_API_URL || 'http://localhost:8000';

  const handleCitySearch = async (e) => {
    e.preventDefault();
    if (!citySearch.trim()) return;

    try {
      const response = await fetch(`${VITE_API_URL}/api/geocode?q=${encodeURIComponent(citySearch)}`);
      if (!response.ok) {
        throw new Error('City not found');
      }
      const data = await response.json();
      setLocation({ lat: data.latitude, lng: data.longitude });
      setBounds(null);
    } catch (err) {
      alert('Error finding city: ' + err.message);
    }
  };

  const getCenterPoint = () => {
    if (bounds) {
      const southWest = bounds[0];
      const northEast = bounds[1];
      const lat = (southWest[0] + northEast[0]) / 2;
      const lng = (southWest[1] + northEast[1]) / 2;
      return { lat, lng };
    }
    return location;
  };

  const getAnalysisParams = () => {
    const point = getCenterPoint();
    return {
      lat: point.lat,
      lon: point.lng,
      start_year: startYear,
      end_year: endYear,
      hazard: hazard
    };
  };

  return (
    <div className="controls-panel">
      <div className="controls-section">
        <h3>Location Selection</h3>
        <div className="location-method">
          <label>
            <input
              type="radio"
              value="city"
              checked={regionBy === 'city'}
              onChange={(e) => setRegionBy(e.target.value)}
            />
            By City
          </label>
          <label>
            <input
              type="radio"
              value="map"
              checked={regionBy === 'map'}
              onChange={(e) => setRegionBy(e.target.value)}
            />
            By Map
          </label>
        </div>

        {regionBy === 'city' && (
          <div className="city-search">
            <form onSubmit={handleCitySearch}>
              <input
                type="text"
                value={citySearch}
                onChange={(e) => setCitySearch(e.target.value)}
                placeholder="Enter city name (e.g., 'New York')"
                disabled={loading}
              />
              <button type="submit" disabled={loading}>
                {loading ? 'Searching...' : 'Search'}
              </button>
            </form>
          </div>
        )}

        {regionBy === 'map' && (
          <div className="map-info">
            <p>Click on the map or draw a rectangle to select location</p>
            {bounds && (
              <p>Selected area: {bounds.length > 0 ? 'Rectangle' : 'Point'}</p>
            )}
          </div>
        )}
      </div>

      <div className="controls-section">
        <h3>Analysis Parameters</h3>
        <div className="parameter-group">
          <label>Hazard Type:</label>
          <select
            value={hazard}
            onChange={(e) => setHazard(e.target.value)}
            disabled={loading}
          >
            <option value="heatwave">Heatwave</option>
            <option value="drought" disabled>Drought (Coming Soon)</option>
            <option value="flood" disabled>Flood (Coming Soon)</option>
          </select>
        </div>

        <div className="parameter-group">
          <label>Start Year:</label>
          <input
            type="number"
            value={startYear}
            onChange={(e) => setStartYear(Math.max(1950, parseInt(e.target.value) || 1950))}
            min="1950"
            max={new Date().getFullYear() - 1}
            disabled={loading}
          />
        </div>

        <div className="parameter-group">
          <label>End Year:</label>
          <input
            type="number"
            value={endYear}
            onChange={(e) => setEndYear(Math.max(parseInt(e.target.value) || startYear + 10, startYear + 10))}
            min={startYear + 10}
            max={new Date().getFullYear() - 1}
            disabled={loading}
          />
          <small>Minimum 10-year span required</small>
        </div>
      </div>

      <div className="controls-section">
        <h3>Actions</h3>
        <button
          onClick={() => onAnalyzeClick(getAnalysisParams())}
          disabled={loading || !analysisData && !location}
          className="primary-button"
        >
          {loading ? 'Analyzing...' : 'Analyze Climate Hazard'}
        </button>

        {analysisData && (
          <button
            onClick={() => onExportClick(getAnalysisParams())}
            disabled={loading}
            className="secondary-button"
          >
            {loading ? 'Exporting...' : 'Download CSV'}
          </button>
        )}
      </div>

      {error && (
        <div className="error-message">
          <strong>Error:</strong> {error}
        </div>
      )}
    </div>
  );
};
